// 引入 jsencrypt 库
// const JSEncrypt = require('jsencrypt');

// 创建 JSEncrypt 实例
const jse = new JSEncrypt();

// 设置 RSA 公钥，这里假设公钥为一个字符串
const publicKey = ``;

// 设置 RSA 公钥
jse.setPublicKey(publicKey);
// 使用公钥加密
const encrypted = jse.encrypt('Hello world');
console.log('加密后的密文:', encrypted);

// 创建 JSEncrypt 实例
const decrypt = new JSEncrypt();

// 这里的 privateKey 是一个假的私钥示例，实际使用中应该在服务端进行解密操作
const privateKey = `
wYraEShFWu8UYFMbQB0rPKEDxjZd5/YFoaQHM0dg3UOpxuUx2TuN1QANWq8GwnWd`;

// 设置 RSA 私钥
decrypt.setPrivateKey(privateKey);

// 使用私钥解密
const decrypted = decrypt.decrypt(encrypted);
console.log('解密后的明文:', decrypted);